begin;
create extension if not exists pgtap with schema extensions;
set search_path to public, extensions;
select plan(15);
grant usage on schema extensions to mcp_import;
grant execute on all functions in schema extensions to mcp_import;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,created_at,updated_at) values
('18220000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','mcp182-tools@example.invalid','x',now(),now());
insert into public.organizations(id,name) values ('18220000-0000-0000-0000-000000000002','Synthetic');
insert into public.organization_members(organization_id,user_id,role) values ('18220000-0000-0000-0000-000000000002','18220000-0000-0000-0000-000000000001','owner');
insert into auth.oauth_clients(id,registration_type,redirect_uris,grant_types,client_type,token_endpoint_auth_method) values ('18220000-0000-0000-0000-000000000003','dynamic','http://localhost/callback','authorization_code','public','none');
insert into auth.oauth_consents(id,user_id,client_id,scopes) values ('18220000-0000-0000-0000-000000000004','18220000-0000-0000-0000-000000000001','18220000-0000-0000-0000-000000000003','openid');
insert into private.mcp_reauth_proofs(user_id,client_id,consent_granted_at,verified_at) select user_id,client_id,granted_at,clock_timestamp() from auth.oauth_consents where id='18220000-0000-0000-0000-000000000004';
insert into auth.sessions(id,user_id,oauth_client_id,created_at) values ('18220000-0000-0000-0000-000000000005','18220000-0000-0000-0000-000000000001','18220000-0000-0000-0000-000000000003',now());
insert into public.user_session_activity(session_hash,auth_session_id,user_id,last_activity,absolute_expires_at) values ('mcp182-tools-browser','mcp182-tools-browser','18220000-0000-0000-0000-000000000001',now(),now()+interval '1 hour');
insert into public.clients(id,organization_id,name) values ('18220000-0000-0000-0000-000000000006','18220000-0000-0000-0000-000000000002','Synthetic client');
insert into public.form_templates(client_id,schema) values ('18220000-0000-0000-0000-000000000006','[{"id":"note","label":"Note","type":"text"}]');
insert into public.reports(id,client_id,helper_id,service_date,status,start_at,end_at) values ('18220000-0000-0000-0000-000000000007','18220000-0000-0000-0000-000000000006','18220000-0000-0000-0000-000000000001','2026-10-28','draft','2026-10-28 01:00+00','2026-10-28 02:00+00');
insert into public.report_values(report_id,data) values ('18220000-0000-0000-0000-000000000007','{"note":"before"}');
insert into public.organizations(id,name) values ('18220000-0000-0000-0000-000000000098','Other synthetic organization');
insert into public.clients(id,organization_id,name) values ('18220000-0000-0000-0000-000000000097','18220000-0000-0000-0000-000000000098','Other synthetic client');
insert into public.reports(id,client_id,helper_id,service_date,status,start_at,end_at) values ('18220000-0000-0000-0000-000000000096','18220000-0000-0000-0000-000000000097','18220000-0000-0000-0000-000000000001','2026-10-28','draft','2026-10-28 01:00+00','2026-10-28 02:00+00');
insert into private.mcp_record_read_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18220000-0000-0000-0000-000000000002',true,'{}','18220000-0000-0000-0000-000000000001',now());
select set_config('test.record_version',(select current_version::text from public.reports where id='18220000-0000-0000-0000-000000000007'),true);
select set_config('request.jwt.claims','{"sub":"18220000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18220000-0000-0000-0000-000000000003","session_id":"18220000-0000-0000-0000-000000000005"}',true);
set local role mcp_import;
select throws_ok($$select public.prepare_mcp_record_edit('18220000-0000-0000-0000-000000000002','18220000-0000-0000-0000-000000000007',current_setting('test.record_version')::bigint,'{"note":"after"}','reason')$$,'42501','proposal_unavailable','MCP prepare rejects disabled edit control');
select throws_ok($$select public.get_mcp_record_edit_template('18220000-0000-0000-0000-000000000002','18220000-0000-0000-0000-000000000007')$$,'42501','proposal_unavailable','MCP template rejects disabled edit control');
reset role;
insert into private.mcp_record_edit_controls(organization_id,enabled,conditions,confirmed_by,confirmed_at) values ('18220000-0000-0000-0000-000000000002',true,'{}','18220000-0000-0000-0000-000000000001',now());
set local role mcp_import;
select is(public.get_mcp_record_edit_template('18220000-0000-0000-0000-000000000002','18220000-0000-0000-0000-000000000007')->'values'->>'note','before','MCP template returns authorized current content');
select throws_ok($$select public.get_mcp_record_edit_template('18220000-0000-0000-0000-000000000002','18220000-0000-0000-0000-000000000099')$$,'42501','proposal_unavailable','MCP template denies unavailable report');
select throws_ok($$select public.get_mcp_record_edit_template('18220000-0000-0000-0000-000000000002','18220000-0000-0000-0000-000000000096')$$,'42501','proposal_unavailable','MCP template denies report from another organization');
select throws_ok($$select public.prepare_mcp_record_edit('18220000-0000-0000-0000-000000000002','18220000-0000-0000-0000-000000000096',0,'{"note":"after"}','reason')$$,'42501','proposal_unavailable','MCP prepare denies report from another organization');
select set_config('test.proposal',(public.prepare_mcp_record_edit('18220000-0000-0000-0000-000000000002','18220000-0000-0000-0000-000000000007',current_setting('test.record_version')::bigint,'{"note":"after"}','reason')->>'proposal_id'),true);
select is(public.get_mcp_record_edit_result('18220000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)->>'status','confirmation_required','MCP sees pending status');
select ok(not has_function_privilege('mcp_import','public.confirm_mcp_record_edit(uuid)','execute'),'MCP cannot call browser confirmation');
select ok(not has_function_privilege('mcp_import','public.get_mcp_record_edit_review(uuid)','execute'),'MCP cannot call browser review');
reset role;
select is((select count(*)::int from public.audit_events where action_type='report.view' and details->>'source'='mcp_record_edit_template'),1,'template access is audited');
select is((select data->>'note' from public.report_values where report_id='18220000-0000-0000-0000-000000000007'),'before','preparation leaves draft unchanged');
select set_config('request.jwt.claims','{"sub":"18220000-0000-0000-0000-000000000001","role":"authenticated","session_id":"mcp182-tools-browser"}',true);
set local role authenticated;
select is(public.get_mcp_record_edit_review(current_setting('test.proposal')::uuid)->>'status','confirmation_required','browser sees review');
select is(public.confirm_mcp_record_edit(current_setting('test.proposal')::uuid)->>'status','updated','browser can confirm');
reset role;
select is((select data->>'note' from public.report_values where report_id='18220000-0000-0000-0000-000000000007'),'after','confirmed draft updated');
select set_config('request.jwt.claims','{"sub":"18220000-0000-0000-0000-000000000001","role":"mcp_import","exp":4102444800,"client_id":"18220000-0000-0000-0000-000000000003","session_id":"18220000-0000-0000-0000-000000000005"}',true);
set local role mcp_import;
select is(public.get_mcp_record_edit_result('18220000-0000-0000-0000-000000000002',current_setting('test.proposal')::uuid)->>'status','updated','MCP sees confirmed result');
reset role;
select * from finish();
rollback;
